using Contoso.Pricing;

namespace Contoso.Pricing.Tests;

[TestClass]
public sealed class PriceCalculatorTests
{
    private PriceCalculator _calculator = null!;

    [TestInitialize]
    public void Setup() => _calculator = new PriceCalculator();

    // ───────────────────────────────────────────────
    // CalculateTotal – DataRow (inline constant data)
    // ───────────────────────────────────────────────

    [TestMethod]
    [DataRow(10.00, 1, 0.0, 10.00, DisplayName = "Single item, no tax")]
    [DataRow(10.00, 5, 0.0, 50.00, DisplayName = "Multiple items, no tax")]
    [DataRow(10.00, 1, 0.10, 11.00, DisplayName = "Single item, 10% tax")]
    [DataRow(25.50, 3, 0.08, 82.62, DisplayName = "Fractional price, 8% tax")]
    [DataRow(0.00, 10, 0.20, 0.00, DisplayName = "Zero price yields zero total")]
    [DataRow(99.99, 0, 0.15, 0.00, DisplayName = "Zero quantity yields zero total")]
    [DataRow(100.00, 2, 1.0, 400.00, DisplayName = "Maximum tax rate (100%)")]
    public void CalculateTotal_WithValidInputs_ReturnsExpectedTotal(
        double unitPrice, int quantity, double taxRate, double expectedTotal)
    {
        var result = _calculator.CalculateTotal((decimal)unitPrice, quantity, (decimal)taxRate);

        Assert.AreEqual((decimal)expectedTotal, result, $"Expected {expectedTotal} but got {result}");
    }

    [TestMethod]
    [DataRow(-1.00, 1, 0.10, "unitPrice", DisplayName = "Negative price throws")]
    [DataRow(10.00, -1, 0.10, "quantity", DisplayName = "Negative quantity throws")]
    [DataRow(10.00, 1, -0.01, "taxRate", DisplayName = "Negative tax rate throws")]
    [DataRow(10.00, 1, 1.01, "taxRate", DisplayName = "Tax rate > 1 throws")]
    public void CalculateTotal_WithInvalidInputs_ThrowsArgumentOutOfRange(
        double unitPrice, int quantity, double taxRate, string expectedParamName)
    {
        var ex = Assert.ThrowsException<ArgumentOutOfRangeException>(
            () => _calculator.CalculateTotal((decimal)unitPrice, quantity, (decimal)taxRate));

        Assert.AreEqual(expectedParamName, ex.ParamName);
    }

    // ───────────────────────────────────────────────
    // ApplyDiscount – DynamicData (complex/generated scenarios)
    // ───────────────────────────────────────────────

    [TestMethod]
    [DynamicData(nameof(ValidDiscountData), DynamicDataSourceType.Method)]
    public void ApplyDiscount_WithValidInputs_ReturnsDiscountedPrice(
        decimal price, decimal discountPercent, decimal expectedResult)
    {
        var result = _calculator.ApplyDiscount(price, discountPercent);

        Assert.AreEqual(expectedResult, result);
    }

    public static IEnumerable<object[]> ValidDiscountData()
    {
        // (price, discountPercent, expected)
        yield return new object[] { 100m, 0m, 100m };      // No discount
        yield return new object[] { 100m, 10m, 90m };      // 10% off
        yield return new object[] { 100m, 50m, 50m };      // Half off
        yield return new object[] { 100m, 100m, 0m };      // Free
        yield return new object[] { 200m, 25m, 150m };     // 25% off $200
        yield return new object[] { 49.99m, 20m, 39.992m }; // Fractional result
        yield return new object[] { 0m, 50m, 0m };         // Zero price
    }

    [TestMethod]
    [DynamicData(nameof(InvalidDiscountData), DynamicDataSourceType.Property)]
    public void ApplyDiscount_WithInvalidDiscount_ThrowsArgumentOutOfRange(
        decimal price, decimal discountPercent)
    {
        Assert.ThrowsException<ArgumentOutOfRangeException>(
            () => _calculator.ApplyDiscount(price, discountPercent));
    }

    public static IEnumerable<object[]> InvalidDiscountData =>
    [
        [100m, -1m],    // Negative discount
        [100m, 101m],   // Over 100%
        [50m, -0.01m],  // Barely negative
        [50m, 100.01m], // Barely over limit
    ];

    // ───────────────────────────────────────────────
    // FormatPrice – DataRow for simple string assertions
    // ───────────────────────────────────────────────

    [TestMethod]
    [DataRow(9.99, "$", "$9.99", DisplayName = "Default USD symbol")]
    [DataRow(1234.5, "€", "€1234.50", DisplayName = "Euro symbol, pad decimals")]
    [DataRow(0.0, "£", "£0.00", DisplayName = "Zero with GBP")]
    public void FormatPrice_ReturnsCorrectlyFormattedString(
        double price, string symbol, string expected)
    {
        var result = _calculator.FormatPrice((decimal)price, symbol);

        Assert.AreEqual(expected, result);
    }
}

